style.css:
@-moz-document domain("youtube.com") {
/* FONDO PRINCIPAL */
    body, ytd-app, #page-manager {
        background-color: #fff9ed !important; 
    }

    /* BARRA SUPERIOR (HEADER) */
    ytd-masthead {
        background-color: #ff85b3 !important; 
    }

    /* EL LOGO DE YOUTUBE EN NARANJA SATURADO */
    /* Este filtro transforma el rojo original en un naranja vibrante */
    ytd-topbar-logo-renderer #logo-icon {
        filter: invert(56%) sepia(85%) saturate(1500%) hue-rotate(345deg) brightness(100%) contrast(105%) !important;
    }

    /* BOTONES DE LIKE Y DISLIKE */
    /* Los hacemos naranja saturado cuando no están presionados */
    ytd-segmented-like-dislike-button-renderer yt-icon {
        color: #ff7800 !important; /* Naranja puro saturado */
    }

    /* Cuando el botón de Like está activo (presionado) */
    ytd-toggle-button-renderer.style-default-active[is-icon-button] {
        color: #4cd137 !important; /* Cambia a Verde Lima para saber que diste Like */
    }

    /* LETRAS GENERALES Y TÍTULOS (Oscuras para contraste) */
    #video-title, #content-text, .title.ytd-guide-entry-renderer, #channel-name {
        color: #310e31 !important; /* Mauve casi negro */
        font-weight: 600 !important;
    }

    /* BARRA DE BÚSQUEDA NARANJA */
    ytd-searchbox #container.ytd-searchbox {
        border: 3px solid #ff7800 !important;
        border-radius: 20px 0 0 20px !important;
    }

    ytd-searchbox #search-icon-legacy.ytd-searchbox {
        background-color: #ff7800 !important;
    }

    /* BOTÓN SUSCRIBIRSE (Verde Lima) */
    ytd-subscribe-button-renderer paper-button, 
    #install-style-button,
    .yt-spec-button-shape-next--filled.yt-spec-button-shape-next--mono {
        background-color: #4cd137 !important;
        color: #000 !important;
    }

    /* MINIATURAS CON MARCO NARANJA */
    #thumbnail.ytd-thumbnail {
        border-radius: 12px !important;
        border: 3px solid #ff7800 !important;
    }

    /* BARRA DE PROGRESO DEL VIDEO */
    .ytp-play-progress {
        background-color: #ff7800 !important;
    }
}
